     1	package hotel.reservations;
     2	
     3	import hotel.rooms.Room;
     4	import hotel.rooms.RoomType;
     5	import java.math.BigDecimal;
     6	import java.math.RoundingMode;
     7	import java.time.LocalDate;
     8	import java.time.Month;
     9	
    10	/**
    11	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    12	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    13	 * (half-even) at every step.
    14	 */
    15	public final class PriceCalculator {
    16	
    17	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    18	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    19	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
    20	
    21	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
    22	        return switch (ratePlan) {
    23	            case WEEKEND_PACKAGE -> calculateWeekendPackage(room, checkIn, checkOut);
    24	            default -> calculateRegularStay(room, checkIn, checkOut, ratePlan, companyCode);
    25	        };
    26	    }
    27	
    28	    private Price calculateWeekendPackage(Room room, LocalDate checkIn, LocalDate checkOut) {
    29	        BigDecimal fixedPrice = getWeekendPackagePrice(room.type());
    30	        return new Price(2, fixedPrice, cents(BigDecimal.ZERO), fixedPrice);
    31	    }
    32	
    33	    private BigDecimal getWeekendPackagePrice(RoomType roomType) {
    34	        return switch (roomType) {
    35	            case STANDARD -> cents(new BigDecimal("520.00"));
    36	            case DELUXE -> cents(new BigDecimal("820.00"));
    37	            case SUITE -> cents(new BigDecimal("1200.00"));
    38	        };
    39	    }
    40	
    41	    private Price calculateRegularStay(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
    42	        int nights = 0;
    43	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    44	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    45	            subtotal = subtotal.add(nightPrice(room, night));
    46	            nights++;
    47	        }
    48	        BigDecimal discount = switch (ratePlan) {
    49	            case STANDARD -> cents(BigDecimal.ZERO);
    50	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    51	            case CORPORATE -> cents(subtotal.multiply(getCompanyDiscount(companyCode)));
    52	            case LONG_STAY -> cents(subtotal.multiply(LONG_STAY_DISCOUNT));
    53	            case WEEKEND_PACKAGE -> cents(BigDecimal.ZERO); // not reachable but needed for completeness
    54	        };
    55	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    56	    }
    57	
    58	    private BigDecimal getCompanyDiscount(String companyCode) {
    59	        return switch (companyCode) {
    60	            case "TECNOSUL" -> new BigDecimal("0.12");
    61	            case "AGROVALE" -> new BigDecimal("0.18");
    62	            case "FARMAVIDA" -> new BigDecimal("0.25");
    63	            default -> BigDecimal.ZERO;
    64	        };
    65	    }
    66	
    67	    BigDecimal nightPrice(Room room, LocalDate night) {
    68	        BigDecimal nightlyRate = room.nightlyRate();
    69	        if (isHighSeason(night)) {
    70	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    71	        }
    72	        return cents(nightlyRate);
    73	    }
    74	
    75	    /** High season: from December 15 to the end of February, and the whole of July. */
    76	    static boolean isHighSeason(LocalDate date) {
    77	        Month month = date.getMonth();
    78	        return month == Month.JANUARY
    79	                || month == Month.FEBRUARY
    80	                || month == Month.JULY
    81	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    82	    }
    83	
    84	    static BigDecimal cents(BigDecimal value) {
    85	        return value.setScale(2, RoundingMode.HALF_EVEN);
    86	    }
    87	}
