    21	    public ReservationService(
    22	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    23	        this.rooms = rooms;
    24	        this.store = store;
    25	        this.priceCalculator = priceCalculator;
    26	        this.emailSender = emailSender;
    27	    }
    28	
    29	    public synchronized Reservation create(NewReservation request) {
    30	        if (!request.checkOut().isAfter(request.checkIn())) {
    31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    32	        }
    33	        if (request.guests() < 1) {
    34	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    35	        }
    36	        validateRatePlan(request);
    37	        Room room = rooms.find(request.roomNumber())
    38	                .orElseThrow(() -> new HotelException(
    39	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    40	        if (request.guests() > room.capacity()) {
    41	            throw new HotelException(
    42	                    ErrorCode.CAPACITY_EXCEEDED,
    43	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    44	        }
    45	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    46	            throw new HotelException(
    47	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    48	        }
    49	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
    50	        return store.add(request, price);
    51	    }
    52	
    53	    private void validateRatePlan(NewReservation request) {
    54	        switch (request.ratePlan()) {
    55	            case CORPORATE -> {
    56	                if (!isValidCorporateCode(request.companyCode())) {
    57	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "invalid company code for corporate plan");
    58	                }
    59	            }
    60	            case WEEKEND_PACKAGE -> {
    61	                if (!isWeekendStay(request.checkIn(), request.checkOut())) {
    62	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must be Friday to Sunday");
    63	                }
    64	            }
    65	            case LONG_STAY -> {
    66	                int nights = countNights(request.checkIn(), request.checkOut());
    67	                if (nights < 7) {
    68	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "long stay requires at least 7 nights");
    69	                }
    70	            }
    71	            default -> {
    72	            }
    73	        }
    74	    }
    75	
    76	    private boolean isValidCorporateCode(String companyCode) {
    77	        return "TECNOSUL".equals(companyCode) || "AGROVALE".equals(companyCode) || "FARMAVIDA".equals(companyCode);
    78	    }
    79	
    80	    private boolean isWeekendStay(LocalDate checkIn, LocalDate checkOut) {
    81	        int nights = countNights(checkIn, checkOut);
    82	        return nights == 2 && checkIn.getDayOfWeek() == DayOfWeek.FRIDAY && checkOut.getDayOfWeek() == DayOfWeek.SUNDAY;
    83	    }
    84	
    85	    private int countNights(LocalDate checkIn, LocalDate checkOut) {
    86	        int nights = 0;
    87	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    88	            nights++;
    89	        }
    90	        return nights;
    91	    }
    92	
    93	    public Reservation find(long reservationId) {
    94	        return store.find(reservationId)
    95	                .orElseThrow(() -> new HotelException(
    96	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    97	    }
    98	
    99	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
   100	    public synchronized Reservation confirm(long reservationId) {
   101	        Reservation reservation = find(reservationId);
   102	        if (reservation.status() != ReservationStatus.PENDING) {
   103	            throw notAllowed(reservation, "confirm");
   104	        }
   105	        reservation.confirmPayment();
   106	        store.update(reservation);
   107	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
   108	        emailSender.send(
   109	                reservation.guest().email(),
   110	                "Reserva confirmada - " + HOTEL_NAME,
   111	                confirmationEmailBody(reservation, receipt));
   112	        return reservation;
   113	    }
   114	
   115	    /**
   116	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
   117	     * reservation was never paid, so nothing comes back).
   118	     */
   119	    public synchronized Reservation cancel(long reservationId) {
   120	        Reservation reservation = find(reservationId);
   121	        if (reservation.status() != ReservationStatus.PENDING
   122	                && reservation.status() != ReservationStatus.CONFIRMED) {
   123	            throw notAllowed(reservation, "cancel");
   124	        }
   125	        BigDecimal refund = switch (reservation.ratePlan()) {
   126	            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
   127	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
   128	            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().multiply(new BigDecimal("0.5")));
   129	        };
   130	        reservation.cancel(refund);
   131	        store.update(reservation);
   132	        return reservation;
   133	    }
   134	
   135	    public synchronized Reservation checkIn(long reservationId) {
   136	        Reservation reservation = find(reservationId);
   137	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   138	            throw notAllowed(reservation, "check in");
   139	        }
   140	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   141	        store.update(reservation);
   142	        return reservation;
   143	    }
   144	
   145	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   146	    public synchronized ReservationReceipt checkOut(long reservationId) {
   147	        Reservation reservation = find(reservationId);
   148	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   149	            throw notAllowed(reservation, "check out");
   150	        }
   151	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   152	        store.update(reservation);
   153	        return new ReservationReceipt(reservation, roomOf(reservation));
   154	    }
   155	
   156	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   157	    public ReservationReceipt receiptCopy(long reservationId) {
   158	        Reservation reservation = find(reservationId);
   159	        if (!reservation.isPaid()) {
   160	            throw notAllowed(reservation, "issue a receipt for");
   161	        }
   162	        return new ReservationReceipt(reservation, roomOf(reservation));
   163	    }
   164	
   165	    private Room roomOf(Reservation reservation) {
   166	        return rooms.find(reservation.roomNumber()).orElseThrow();
   167	    }
   168	
   169	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   170	        return "Olá, " + reservation.guest().name() + "!\n\n"
   171	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   172	                + receipt.text() + "\n"
   173	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   174	                + "Até breve!\n";
   175	    }
   176	
   177	    private static HotelException notAllowed(Reservation reservation, String operation) {
   178	        return new HotelException(
   179	                ErrorCode.OPERATION_NOT_ALLOWED,
   180	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   181	    }
